#include <iostream>
#include <string>

class Person {
public:
    // Consistency: Default constructor
    Person() : birthYear(2000), name("Unknown") {}

    // Overloaded constructor
    Person(std::string personName, int year) 
        : birthYear(year), name(std::move(personName)) {}

    // Encapsulation: Getter for name
    std::string getName() const {
        return name;
    }

    // Clarity & Independent properties: compute age dynamically rather than storing it
    int getAge(int currentYear) const {
        return currentYear - birthYear;
    }

    int getBirthYear() const {
        return birthYear;
    }

private:
    // Fields are private
    int birthYear;
    std::string name;
    // Notice: 'age' is intentionally NOT stored here!
};

int main() {
    Person p1("Alice", 1995);
    Person p2; // Uses no-arg constructor

    int currentYear = 2026;
    std::cout << p1.getName() << " born " << p1.getBirthYear() 
              << " age: " << p1.getAge(currentYear) << "\n";
    std::cout << p2.getName() << " born " << p2.getBirthYear() 
              << " age: " << p2.getAge(currentYear) << "\n";

    return 0;
}

#include <iostream>

class Circle {
public:
    Circle() : radius(1.0) {
        ++numberOfObjects;
    }

    explicit Circle(double r) : radius(r) {
        ++numberOfObjects;
    }

    ~Circle() {
        --numberOfObjects;
    }

    // Instance function: accesses instance field
    double getRadius() const {
        return radius;
    }

    // Static function: independent of any individual object
    static int getNumberOfObjects() {
        // Note: 'radius' cannot be accessed here directly!
        return numberOfObjects;
    }

private:
    double radius; // Instance variable
    inline static int numberOfObjects = 0; // C++17 inline static variable
};

int main() {
    std::cout << "Initial count: " << Circle::getNumberOfObjects() << "\n";

    Circle c1(3.5);
    Circle c2(5.0);
    std::cout << "Count after creating c1 and c2: " << Circle::getNumberOfObjects() << "\n";

    {
        Circle c3;
        std::cout << "Inside block, count: " << Circle::getNumberOfObjects() << "\n";
    }

    std::cout << "After block scope, count: " << Circle::getNumberOfObjects() << "\n";
    return 0;
}
